// ============================================================================
// Crypto_DMA_apb: APB4 register wrapper around Crypto_DMA_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/Crypto_DMA.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/Crypto_DMA.md
// ============================================================================
module Crypto_DMA_apb #(
  parameter logic [3:0] AXI_ID = 4'd9
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic [255:0] sl_key,
  input logic sl_valid,
  output logic [3:0] m_awid,
  output logic [31:0] m_awaddr,
  output logic [7:0] m_awlen,
  output logic [2:0] m_awsize,
  output logic [1:0] m_awburst,
  output logic [2:0] m_awprot,
  output logic m_awvalid,
  input logic m_awready,
  output logic [31:0] m_wdata,
  output logic [3:0] m_wstrb,
  output logic m_wlast,
  output logic m_wvalid,
  input logic m_wready,
  input logic [3:0] m_bid,
  input logic [1:0] m_bresp,
  input logic m_bvalid,
  output logic m_bready,
  output logic [3:0] m_arid,
  output logic [31:0] m_araddr,
  output logic [7:0] m_arlen,
  output logic [2:0] m_arsize,
  output logic [1:0] m_arburst,
  output logic [2:0] m_arprot,
  output logic m_arvalid,
  input logic m_arready,
  input logic [3:0] m_rid,
  input logic [31:0] m_rdata,
  input logic [1:0] m_rresp,
  input logic m_rlast,
  input logic m_rvalid,
  output logic m_rready
);
  localparam logic [31:0] ID_VALUE = 32'h5C310100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [30:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd31) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_key256;
  logic          c_decrypt;
  logic          c_key_sel;
  logic [3:0]    c_tag_len;
  logic [255:0]  c_key;
  logic [95:0]   c_iv;
  logic [127:0]  c_tag_in;
  logic [31:0]   c_src_addr;
  logic [31:0]   c_dst_addr;
  logic [15:0]   c_aad_len;
  logic [15:0]   c_txt_len;
  logic          c_start;
  logic          c_busy;
  logic          c_err;
  logic          c_gcm_err;
  logic [2:0]    c_err_code;
  logic          c_tag_ok;
  logic [127:0]  c_tag;
  logic [31:0]   c_cycles;
  logic          c_done;
  logic          c_err_irq;
  Crypto_DMA_top #(.AXI_ID(AXI_ID)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .key256(c_key256),
    .decrypt(c_decrypt),
    .key_sel(c_key_sel),
    .tag_len(c_tag_len),
    .key(c_key),
    .iv(c_iv),
    .tag_in(c_tag_in),
    .sl_key(sl_key),
    .sl_valid(sl_valid),
    .src_addr(c_src_addr),
    .dst_addr(c_dst_addr),
    .aad_len(c_aad_len),
    .txt_len(c_txt_len),
    .start(c_start),
    .busy(c_busy),
    .err(c_err),
    .gcm_err(c_gcm_err),
    .err_code(c_err_code),
    .tag_ok(c_tag_ok),
    .tag(c_tag),
    .cycles(c_cycles),
    .done(c_done),
    .err_irq(c_err_irq),
    .m_awid(m_awid),
    .m_awaddr(m_awaddr),
    .m_awlen(m_awlen),
    .m_awsize(m_awsize),
    .m_awburst(m_awburst),
    .m_awprot(m_awprot),
    .m_awvalid(m_awvalid),
    .m_awready(m_awready),
    .m_wdata(m_wdata),
    .m_wstrb(m_wstrb),
    .m_wlast(m_wlast),
    .m_wvalid(m_wvalid),
    .m_wready(m_wready),
    .m_bid(m_bid),
    .m_bresp(m_bresp),
    .m_bvalid(m_bvalid),
    .m_bready(m_bready),
    .m_arid(m_arid),
    .m_araddr(m_araddr),
    .m_arlen(m_arlen),
    .m_arsize(m_arsize),
    .m_arburst(m_arburst),
    .m_arprot(m_arprot),
    .m_arvalid(m_arvalid),
    .m_arready(m_arready),
    .m_rid(m_rid),
    .m_rdata(m_rdata),
    .m_rresp(m_rresp),
    .m_rlast(m_rlast),
    .m_rvalid(m_rvalid),
    .m_rready(m_rready)
  );

  // ---------------- registers ----------------
  logic [1:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [6:0] r_CTRL;   // 12'h014 CTRL
  logic [31:0] r_KEY0;   // 12'h018 KEY0
  logic [31:0] r_KEY1;   // 12'h01C KEY1
  logic [31:0] r_KEY2;   // 12'h020 KEY2
  logic [31:0] r_KEY3;   // 12'h024 KEY3
  logic [31:0] r_KEY4;   // 12'h028 KEY4
  logic [31:0] r_KEY5;   // 12'h02C KEY5
  logic [31:0] r_KEY6;   // 12'h030 KEY6
  logic [31:0] r_KEY7;   // 12'h034 KEY7
  logic [31:0] r_IV0;   // 12'h038 IV0
  logic [31:0] r_IV1;   // 12'h03C IV1
  logic [31:0] r_IV2;   // 12'h040 IV2
  logic [31:0] r_TAG_IN0;   // 12'h044 TAG_IN0
  logic [31:0] r_TAG_IN1;   // 12'h048 TAG_IN1
  logic [31:0] r_TAG_IN2;   // 12'h04C TAG_IN2
  logic [31:0] r_TAG_IN3;   // 12'h050 TAG_IN3
  logic [31:0] r_SRC_ADDR;   // 12'h054 SRC_ADDR
  logic [31:0] r_DST_ADDR;   // 12'h058 DST_ADDR
  logic [31:0] r_LEN;   // 12'h05C LEN
  logic [0:0] p_CMD;   // 12'h060 CMD (pulses)

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_CTRL <= 7'h0;
      r_KEY0 <= 32'h0;
      r_KEY1 <= 32'h0;
      r_KEY2 <= 32'h0;
      r_KEY3 <= 32'h0;
      r_KEY4 <= 32'h0;
      r_KEY5 <= 32'h0;
      r_KEY6 <= 32'h0;
      r_KEY7 <= 32'h0;
      r_IV0 <= 32'h0;
      r_IV1 <= 32'h0;
      r_IV2 <= 32'h0;
      r_TAG_IN0 <= 32'h0;
      r_TAG_IN1 <= 32'h0;
      r_TAG_IN2 <= 32'h0;
      r_TAG_IN3 <= 32'h0;
      r_SRC_ADDR <= 32'h0;
      r_DST_ADDR <= 32'h0;
      r_LEN <= 32'h0;
      p_CMD <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[1:0] & wmask[1:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[1:0]) | (PWDATA[1:0] & wmask[1:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_CTRL <= (r_CTRL & ~wmask[6:0]) | (PWDATA[6:0] & wmask[6:0]);
      if (wr && hit[6]) r_KEY0 <= (r_KEY0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[7]) r_KEY1 <= (r_KEY1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[8]) r_KEY2 <= (r_KEY2 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[9]) r_KEY3 <= (r_KEY3 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[10]) r_KEY4 <= (r_KEY4 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[11]) r_KEY5 <= (r_KEY5 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[12]) r_KEY6 <= (r_KEY6 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[13]) r_KEY7 <= (r_KEY7 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[14]) r_IV0 <= (r_IV0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[15]) r_IV1 <= (r_IV1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[16]) r_IV2 <= (r_IV2 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[17]) r_TAG_IN0 <= (r_TAG_IN0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[18]) r_TAG_IN1 <= (r_TAG_IN1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[19]) r_TAG_IN2 <= (r_TAG_IN2 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[20]) r_TAG_IN3 <= (r_TAG_IN3 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[21]) r_SRC_ADDR <= (r_SRC_ADDR & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[22]) r_DST_ADDR <= (r_DST_ADDR & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[23]) r_LEN <= (r_LEN & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      p_CMD <= (wr && hit[24]) ? PWDATA[0:0] & wmask[0:0] : '0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_key256 = r_CTRL[0:0];
  assign c_decrypt = r_CTRL[1:1];
  assign c_key_sel = r_CTRL[2:2];
  assign c_tag_len = r_CTRL[6:3];
  assign c_key[31:0] = r_KEY0[31:0];
  assign c_key[63:32] = r_KEY1[31:0];
  assign c_key[95:64] = r_KEY2[31:0];
  assign c_key[127:96] = r_KEY3[31:0];
  assign c_key[159:128] = r_KEY4[31:0];
  assign c_key[191:160] = r_KEY5[31:0];
  assign c_key[223:192] = r_KEY6[31:0];
  assign c_key[255:224] = r_KEY7[31:0];
  assign c_iv[31:0] = r_IV0[31:0];
  assign c_iv[63:32] = r_IV1[31:0];
  assign c_iv[95:64] = r_IV2[31:0];
  assign c_tag_in[31:0] = r_TAG_IN0[31:0];
  assign c_tag_in[63:32] = r_TAG_IN1[31:0];
  assign c_tag_in[95:64] = r_TAG_IN2[31:0];
  assign c_tag_in[127:96] = r_TAG_IN3[31:0];
  assign c_src_addr = r_SRC_ADDR[31:0];
  assign c_dst_addr = r_DST_ADDR[31:0];
  assign c_aad_len = r_LEN[15:0];
  assign c_txt_len = r_LEN[31:16];
  assign c_start = p_CMD;

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_done;
    irq_set[1] = c_err_irq;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_CTRL);
      10'd14: apb_rdata = 32'(r_IV0);
      10'd15: apb_rdata = 32'(r_IV1);
      10'd16: apb_rdata = 32'(r_IV2);
      10'd17: apb_rdata = 32'(r_TAG_IN0);
      10'd18: apb_rdata = 32'(r_TAG_IN1);
      10'd19: apb_rdata = 32'(r_TAG_IN2);
      10'd20: apb_rdata = 32'(r_TAG_IN3);
      10'd21: apb_rdata = 32'(r_SRC_ADDR);
      10'd22: apb_rdata = 32'(r_DST_ADDR);
      10'd23: apb_rdata = 32'(r_LEN);
      10'd25: apb_rdata = 32'({c_tag_ok, c_err_code, c_gcm_err, c_err, c_busy});
      10'd26: apb_rdata = 32'({c_tag[31:0]});
      10'd27: apb_rdata = 32'({c_tag[63:32]});
      10'd28: apb_rdata = 32'({c_tag[95:64]});
      10'd29: apb_rdata = 32'({c_tag[127:96]});
      10'd30: apb_rdata = 32'({c_cycles});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
